window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2fd43af179c56719"]={"versions": [{"id": "FIG-2fd43af179c56719", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur E2E-Absicherung beim Empfang von Kommunikationsdaten in der AUTOSAR Classic Platform (SWS E2E Library). Das Diagramm stellt das Zusammenwirken zwischen einer empfangenden Instanz (Receiver of I-PDUs), dem E2E-Bibliotheksmodul, der CRC-Bibliothek und dem PDU-Router (PduR) im Rahmen der Datenabholung und E2E-Prüfung dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert vier Lifelines:</p>\n<ul class=\"fig-list\">\n<li><code>Receiver of I-PDUs</code>: Empfängerkomponente (z. B. COM, SW-C oder RTE-Komponente).</li>\n<li><code>E2E Library</code>: AUTOSAR E2E-Bibliothek mit E2E-Prüfroutinen.</li>\n<li><code>CRC Library</code>: AUTOSAR CRC-Bibliothek zur zyklischen Redundanzprüfung.</li>\n<li><code>«module» PduR</code>: AUTOSAR PDU Router als PDU-Bereitsteller.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\">\n<li><code>read I-PDU :Read_Status</code>: Synchroner Abrufaufruf an PduR mit Rückgabestatus <code>Read_Status</code>.</li>\n<li><code>E2E_P01Check(Config, State, Data)</code>: E2E-Prüffunktion (beispielhaft für Profil 1) mit Parametern <code>Config</code> (Konfigurationsstruktur), <code>State</code> (Zustandsstruktur) und <code>Data</code> (Zeiger auf die I-PDU-Nutzdaten als <code>uint8*</code>), Rückgabewert <code>ret</code>.</li>\n<li><code>Crc_CalculateCRCx</code>: Aufruf an die CRC-Bibliothek zur Prüfsummenberechnung bei Profil 1 und 2.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Sequenz des Empfangsprozesses:</p>\n<ol class=\"fig-list\">\n<li><code>[At Receiver startup]</code>: Initialer Selbstaufruf des Receivers zur Instanziierung und Initialisierung der <code>Config</code>- und <code>State</code>-Strukturen.</li>\n<li>Der Receiver ruft an PduR <code>read I-PDU :Read_Status</code> auf, um eine neue PDU abzufragen.</li>\n<li>Intern setzt der Receiver das Flag <code>State-&gt;NewDataAvailable = TRUE</code>.</li>\n<li>Der Datenzeiger wird auf die Nutzdaten gecastet: <code>Data = (uint8*) I-PDU</code>.</li>\n<li>Aufruf der Prüffunktion <code>E2E_P01Check(Config, State, Data)</code> an der E2E Library.</li>\n<li>Innerhalb der E2E Library:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Interner Aufruf <code>Execute library logic, e.g. check all control fields</code>.</li>\n<li>Bedingter Aufruf <code>[In case E2E Profile 1 and 2]:Use Crc_CalculateCRCx to calculate CRC</code> an die CRC Library.</li>\n<li>Interner Aufruf <code>update State depending on checks</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Rückkehr von E2E Library an den Receiver mit Status <code>ret</code>.</li>\n<li>Interner Selbstaufruf am Receiver: <code>Evaluate ret and handle library internal errors, e.g. report to DEM</code>.</li>\n<li>Interner Selbstaufruf am Receiver: <code>Update signals with the content from I-PDU</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Entwurfs- und Implementierungsvorgaben für E2E-geschützte Empfangspfade:</p>\n<ul class=\"fig-list\">\n<li>Der Receiver muss vor der ersten Prüfung die Konfigurations- und Statusstrukturen korrekt initialisieren.</li>\n<li>Die E2E-Prüfung erfolgt auf Roh-Byteebene (<code>uint8*</code>) vor dem Signal-Unpacking.</li>\n<li>Die E2E-Bibliothek ist zustandslos bezüglich der Speicherung von Instanzdaten; der Zustand wird vollständig über die vom Aufrufer übergebene <code>State</code>-Struktur gehalten und aktualisiert.</li>\n<li>Fehlerbehandlung (inklusive Fehlermeldung an das Diagnostic Event Manager Modul, DEM) und die Aktualisierung der Signale bei gültigen Daten liegen in der Verantwortung des Aufrufers (<code>Receiver of I-PDUs</code>).</li>\n</ul>"}, {"id": "FIG-601772ef6f2c6ad6", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur E2E-Absicherung beim Empfang von Kommunikationsdaten in der AUTOSAR Classic Platform (SWS E2E Library). Das Diagramm stellt das Zusammenwirken zwischen einer empfangenden Instanz (Receiver of I-PDUs), dem E2E-Bibliotheksmodul, der CRC-Bibliothek und dem PDU-Router (PduR) im Rahmen der Datenabholung und E2E-Prüfung dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert vier Lifelines:</p>\n<ul class=\"fig-list\">\n<li><code>Receiver of I-PDUs</code>: Empfängerkomponente (z. B. COM, SW-C oder RTE-Komponente).</li>\n<li><code>E2E Library</code>: AUTOSAR E2E-Bibliothek mit E2E-Prüfroutinen.</li>\n<li><code>CRC Library</code>: AUTOSAR CRC-Bibliothek zur zyklischen Redundanzprüfung.</li>\n<li><code>«module» PduR</code>: AUTOSAR PDU Router als PDU-Bereitsteller.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\">\n<li><code>read I-PDU :Read_Status</code>: Synchroner Abrufaufruf an PduR mit Rückgabestatus <code>Read_Status</code>.</li>\n<li><code>E2E_P01Check(Config, State, Data)</code>: E2E-Prüffunktion (beispielhaft für Profil 1) mit Parametern <code>Config</code> (Konfigurationsstruktur), <code>State</code> (Zustandsstruktur) und <code>Data</code> (Zeiger auf die I-PDU-Nutzdaten als <code>uint8*</code>), Rückgabewert <code>ret</code>.</li>\n<li><code>Crc_CalculateCRCx</code>: Aufruf an die CRC-Bibliothek zur Prüfsummenberechnung bei Profil 1 und 2.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Sequenz des Empfangsprozesses:</p>\n<ol class=\"fig-list\">\n<li><code>[At Receiver startup]</code>: Initialer Selbstaufruf des Receivers zur Instanziierung und Initialisierung der <code>Config</code>- und <code>State</code>-Strukturen.</li>\n<li>Der Receiver ruft an PduR <code>read I-PDU :Read_Status</code> auf, um eine neue PDU abzufragen.</li>\n<li>Intern setzt der Receiver das Flag <code>State-&gt;NewDataAvailable = TRUE</code>.</li>\n<li>Der Datenzeiger wird auf die Nutzdaten gecastet: <code>Data = (uint8*) I-PDU</code>.</li>\n<li>Aufruf der Prüffunktion <code>E2E_P01Check(Config, State, Data)</code> an der E2E Library.</li>\n<li>Innerhalb der E2E Library:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Interner Aufruf <code>Execute library logic, e.g. check all control fields</code>.</li>\n<li>Bedingter Aufruf <code>[In case E2E Profile 1 and 2]:Use Crc_CalculateCRCx to calculate CRC</code> an die CRC Library.</li>\n<li>Interner Aufruf <code>update State depending on checks</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Rückkehr von E2E Library an den Receiver mit Status <code>ret</code>.</li>\n<li>Interner Selbstaufruf am Receiver: <code>Evaluate ret and handle library internal errors, e.g. report to DEM</code>.</li>\n<li>Interner Selbstaufruf am Receiver: <code>Update signals with the content from I-PDU</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Entwurfs- und Implementierungsvorgaben für E2E-geschützte Empfangspfade:</p>\n<ul class=\"fig-list\">\n<li>Der Receiver muss vor der ersten Prüfung die Konfigurations- und Statusstrukturen korrekt initialisieren.</li>\n<li>Die E2E-Prüfung erfolgt auf Roh-Byteebene (<code>uint8*</code>) vor dem Signal-Unpacking.</li>\n<li>Die E2E-Bibliothek ist zustandslos bezüglich der Speicherung von Instanzdaten; der Zustand wird vollständig über die vom Aufrufer übergebene <code>State</code>-Struktur gehalten und aktualisiert.</li>\n<li>Fehlerbehandlung (inklusive Fehlermeldung an das Diagnostic Event Manager Modul, DEM) und die Aktualisierung der Signale bei gültigen Daten liegen in der Verantwortung des Aufrufers (<code>Receiver of I-PDUs</code>).</li>\n</ul>"}, {"id": "FIG-d05bb8d22207bf34", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur E2E-Absicherung beim Empfang von Kommunikationsdaten in der AUTOSAR Classic Platform (SWS E2E Library). Das Diagramm stellt das Zusammenwirken zwischen einer empfangenden Instanz (Receiver of I-PDUs), dem E2E-Bibliotheksmodul, der CRC-Bibliothek und dem PDU-Router (PduR) im Rahmen der Datenabholung und E2E-Prüfung dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert vier Lifelines:</p>\n<ul class=\"fig-list\">\n<li><code>Receiver of I-PDUs</code>: Empfängerkomponente (z. B. COM, SW-C oder RTE-Komponente).</li>\n<li><code>E2E Library</code>: AUTOSAR E2E-Bibliothek mit E2E-Prüfroutinen.</li>\n<li><code>CRC Library</code>: AUTOSAR CRC-Bibliothek zur zyklischen Redundanzprüfung.</li>\n<li><code>«module» PduR</code>: AUTOSAR PDU Router als PDU-Bereitsteller.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\">\n<li><code>read I-PDU: Read_Status</code>: Synchroner Abrufaufruf an PduR mit expliziter Rückkehrantwort.</li>\n<li><code>E2E_P01Check(Config, State, Data)</code>: E2E-Prüffunktion (beispielhaft für Profil 1) mit Parametern <code>Config</code> (Konfigurationsstruktur), <code>State</code> (Zustandsstruktur) und <code>Data</code> (Zeiger auf die I-PDU-Nutzdaten als <code>uint8*</code>), Rückgabewert <code>ret</code>.</li>\n<li><code>Crc_CalculateCRCx()</code>: Synchroner Aufruf an die CRC-Bibliothek zur Berechnung der Prüfsumme über <code>DataID</code> und <code>Date</code> (Data) für die Profile 1, 2, 11 und 22 mit expliziter Rückkehr zur E2E Library.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Sequenz des Empfangsprozesses:</p>\n<ol class=\"fig-list\">\n<li><code>[At Receiver startup]</code>: Initialer Selbstaufruf des Receivers zur Instanziierung und Initialisierung der <code>Config</code>- und <code>State</code>-Strukturen.</li>\n<li>Der Receiver ruft an PduR <code>read I-PDU: Read_Status</code> auf; PduR antwortet mit einem synchronen Rückkehrpfeil an den Receiver.</li>\n<li>Intern setzt der Receiver das Flag <code>State-&gt;NewDataAvailable = TRUE</code>.</li>\n<li>Der Datenzeiger wird auf die Nutzdaten gecastet: <code>Data = (uint8*) I-PDU</code>.</li>\n<li>Aufruf der Prüffunktion <code>E2E_P01Check(Config, State, Data)</code> an der E2E Library.</li>\n<li>Innerhalb der E2E Library:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Interner Aufruf <code>Execute library logic, e.g. check all control fields</code>.</li>\n<li>Bedingter Aufruf <code>[In case E2E Profile 1,2, 11 and 22]: Use Crc_CalculateCRCx() to calculate CRC over DataID and Date</code> an die CRC Library; die CRC Library liefert das Ergebnis synchron an die E2E Library zurück.</li>\n<li>Interner Aufruf <code>update State depending on checks</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Rückkehr von E2E Library an den Receiver mit Status <code>ret</code>.</li>\n<li>Interner Selbstaufruf am Receiver: <code>Evaluate ret and handle library internal errors, e.g. report to DEM</code>.</li>\n<li>Interner Selbstaufruf am Receiver: <code>Update Signals with the Content from I-PDU</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Entwurfs- und Implementierungsvorgaben für E2E-geschützte Empfangspfade:</p>\n<ul class=\"fig-list\">\n<li>Der Receiver muss vor der ersten Prüfung die Konfigurations- und Statusstrukturen korrekt initialisieren.</li>\n<li>Der Abruf über den PDU-Router (<code>read I-PDU</code>) ist als synchrone Abfrage modelliert, die an den Receiver zurückkehrt.</li>\n<li>Die E2E-Prüfung erfolgt auf Roh-Byteebene (<code>uint8*</code>) vor dem Entpacken der Signale.</li>\n<li>Die CRC-Berechnung deckt explizit die Daten-Identifikation (DataID) sowie die Nutzdaten ab und betrifft die standardisierten Profile 1, 2, 11 und 22.</li>\n<li>Fehlerbehandlung (inklusive Meldung an das DEM-Modul) und Signalaktualisierung obliegen der aufrufenden Empfängerinstanz.</li>\n</ul>"}], "trans": [{"from": "FIG-2fd43af179c56719", "to": "FIG-601772ef6f2c6ad6", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-601772ef6f2c6ad6", "to": "FIG-d05bb8d22207bf34", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Interaktionspartner CRC Library: Profilbedingung von <code>[In case E2E Profile 1 and 2]</code> auf <code>[In case E2E Profile 1, 2, 11 and 22]</code> erweitert; Funktionsaufruf syntaktisch zu <code>Crc_CalculateCRCx()</code> ergänzt und Berechnungsbereich explizit als <code>over DataID and Date</code> spezifiziert.</li>\n<li>Interaktionsverlauf CRC Library: Expliziter Rückkehrpfeil vom Aktivierungsbalken der CRC Library zurück zum Aktivierungsbalken der E2E Library ergänzt.</li>\n<li>Interaktionsverlauf PduR: Rückkehrpfeil von PduR zum Receiver of I-PDUs für <code>read I-PDU: Read_Status</code> ergänzt.</li>\n<li>Letzter Selbstaufruf Receiver of I-PDUs: Beschriftung von <code>Update signals with the content from I-PDU</code> auf <code>Update Signals with the Content from I-PDU</code> geändert (Layout-Umbruch und Großschreibung von „Signals“ und „Content“).</li>\n</ul>"}]};
